sp_widget.client_script:
api.controller = function($scope, $timeout, $element, spModal) {

  /* =========================================================
     GATENOW · REPORTS AND CHANGE REQUESTS · Client script

     Reading is local. The two submits are real writes, so they
     go to the server and then reload the page data, which is
     the one time a repaint is the correct thing to do.
     ========================================================= */

  var c = this;

  c.query  = '';
  c.tab    = 'reports';
  c.form   = '';       /* '', 'report' or 'change' */
  c.openR  = null;
  c.openC  = null;
  c.saving = false;
  c.errors = {};
  c.files  = [];
  c.dragging = false;

  var UPLOAD = {
    MAX: 10485760,
    TYPES: [
      'application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'image/jpeg', 'image/jpg', 'image/png'
    ],
    EXTS: ['.pdf', '.doc', '.docx', '.jpg', '.jpeg', '.png']
  };

  /* the four ratings, each with its own comment field, declared
     once rather than written out four times in the template */
  c.ratingGroups = [
    { key: 'schedule',  choices: 'schedule',  label: c.data.t.fSchedule,
      comment: 'comments_on_schedule', commentLabel: c.data.t.fCSchedule },
    { key: 'cost',      choices: 'cost',      label: c.data.t.fCost,
      comment: 'comments_on_cost',     commentLabel: c.data.t.fCCost },
    { key: 'resources', choices: 'resources', label: c.data.t.fResources,
      comment: 'resource_comments',    commentLabel: c.data.t.fCResource },
    { key: 'scope',     choices: 'scope',     label: c.data.t.fScope,
      comment: 'comments_on_scope',    commentLabel: c.data.t.fCScope }
  ];


  /* =====================================================
     LISTS
     ===================================================== */

  function hit(text, q) {
    return (text || '').toLowerCase().indexOf(q) !== -1;
  }

  c.visibleReports = function() {
    var q = (c.query || '').trim().toLowerCase();
    if (!q) return c.data.reports || [];
    return (c.data.reports || []).filter(function(r) {
      return hit(r.project, q) || hit(r.number, q) || hit(r.period, q) || hit(r.type, q);
    });
  };

  c.visibleChanges = function() {
    var q = (c.query || '').trim().toLowerCase();
    if (!q) return c.data.changes || [];
    return (c.data.changes || []).filter(function(ch) {
      return hit(ch.project, q) || hit(ch.number, q) || hit(ch.title, q) || hit(ch.category, q);
    });
  };


  /* only the outcomes with something in them. Filtered here
     rather than with ng-if on the repeat, because ng-repeat and
     ng-if on one element each make a child scope and the pair
     is not worth debugging. */
  c.changeStats = function() {
    return (c.data.changeStats || []).filter(function(st) {
      return st.count > 0;
    });
  };


  /* =====================================================
     DETAIL
     ===================================================== */

  c.openReport = function(r) { c.openR = r; c.openC = null; };
  c.openChange = function(ch) { c.openC = ch; c.openR = null; };

  c.closeDetail = function() { c.openR = null; c.openC = null; };

  /* only the blocks that were actually filled in, so a sparse
     report does not render six empty headings */
  c.reportProse = function(r) {
    if (!r) return [];

    var rows = [
      { label: c.data.t.fSummary,   value: r.summary },
      { label: c.data.t.fAchieved,  value: r.achieved },
      { label: c.data.t.fNextUp,    value: r.nextUp },
      { label: c.data.t.fCSchedule, value: r.cSchedule },
      { label: c.data.t.fCCost,     value: r.cCost },
      { label: c.data.t.fCResource, value: r.cResource },
      { label: c.data.t.fCScope,    value: r.cScope },
      { label: c.data.t.fComments,  value: r.comments }
    ];

    return rows.filter(function(row) { return !!row.value; });
  };


  /* =====================================================
     FORMS
     ===================================================== */

  function blankReport() {
    return {
      project: '',
      status_date: c.data.today || '',
      report_status: '',
      percent_complete: null,
      overall_health: '',
      executive_summary: '',
      comments: '',
      achievements_last_month: '',
      key_activities_next_month: '',
      schedule: '', comments_on_schedule: '',
      cost: '', comments_on_cost: '',
      resources: '', resource_comments: '',
      scope: '', comments_on_scope: ''
    };
  }

  function blankChange() {
    return {
      project: '',
      title: '',
      category: '',
      priority: '',
      impact: '',
      proposed_change: '',
      reason_for_change: ''
    };
  }

  c.report = blankReport();
  c.change = blankChange();

  c.startReport = function() {
    c.report = blankReport();

    /* if only one project is open, there is no choice to make */
    var open = (c.data.projects || []).filter(function(p) { return p.open; });
    if (open.length === 1) c.report.project = open[0].sysId;

    c.errors = {};
    c.files = [];
    c.form = 'report';
  };

  c.startChange = function() {
    c.change = blankChange();

    var openC = (c.data.projects || []).filter(function(p) { return p.open; });
    if (openC.length === 1) c.change.project = openC[0].sysId;

    c.errors = {};
    c.files = [];
    c.form = 'change';
  };

  c.closeForm = function() {
    if (c.saving) return;
    c.form = '';
    c.errors = {};
    c.files = [];
  };

  c.errorCount = function() {
    var n = 0;
    for (var k in c.errors) { if (c.errors.hasOwnProperty(k)) n++; }
    return n;
  };

  function empty(v) {
    return v === undefined || v === null || v === '' ||
           (typeof v === 'string' && v.trim() === '');
  }


  /* =====================================================
     ATTACHMENTS

     A dragged file, and an older .doc, often arrive with an
     empty or unexpected type, so the extension is the fallback
     rather than rejecting them silently.
     ===================================================== */

  function typeOk(file) {
    if (file.type && UPLOAD.TYPES.indexOf(file.type) !== -1) return true;

    var name = (file.name || '').toLowerCase();
    for (var i = 0; i < UPLOAD.EXTS.length; i++) {
      var ext = UPLOAD.EXTS[i];
      if (name.length > ext.length && name.slice(-ext.length) === ext) return true;
    }
    return false;
  }

  function already(file) {
    for (var i = 0; i < c.files.length; i++) {
      if (c.files[i].name === file.name && c.files[i].size === file.size) return true;
    }
    return false;
  }

  c.addFiles = function($files) {
    if (!$files || !$files.length) return;

    angular.forEach($files, function(file) {
      if (!file) return;

      if (file.size > UPLOAD.MAX) {
        spModal.open({
          title: c.data.t.tooBigTitle,
          message: '"' + file.name + '" ' + c.data.t.tooBigText,
          buttons: [{ label: c.data.t.ok, primary: true }]
        });
        return;
      }

      if (!typeOk(file)) {
        spModal.open({
          title: c.data.t.badTypeTitle,
          message: '"' + file.name + '" ' + c.data.t.badTypeText,
          buttons: [{ label: c.data.t.ok, primary: true }]
        });
        return;
      }

      /* choosing the same file twice would attach it twice */
      if (already(file)) return;

      c.files.push(file);
    });

    /* the picker fires outside a digest, so the list needs a
       nudge to appear */
    $timeout(function() {});
  };

  c.removeFile = function(i) {
    if (i >= 0 && i < c.files.length) c.files.splice(i, 1);
  };

  c.fileSize = function(bytes) {
    if (!bytes) return '0 B';
    var k = 1024;
    var units = ['B', 'KB', 'MB', 'GB'];
    var i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round(bytes / Math.pow(k, i) * 10) / 10 + ' ' + units[i];
  };

  /* =====================================================
     FILE INPUT AND DROPZONE WIRING

     ng-file-upload is not part of the Service Portal AngularJS
     bundle, so ngf-select and ngf-drop never bound and the
     picker never opened. This wires a native input instead.

     Both forms live inside an ng-if, so their DOM is built
     fresh every time one opens and the listeners have to be
     attached then. The freshly created element carries no bound
     flag, so it wires exactly once per opening.
     ===================================================== */

  c.pickFiles = function() {
    var input = $element[0].querySelector('.grc-file-input');
    if (input) input.click();
  };

  function bindDropzone() {
    var drop  = $element[0].querySelector('.grc-drop');
    var input = $element[0].querySelector('.grc-file-input');
    if (!drop || !input) return;

    if (drop.getAttribute('data-grc-bound') === '1') return;
    drop.setAttribute('data-grc-bound', '1');

    input.addEventListener('change', function(e) {
      var files = e.target.files;
      $scope.$apply(function() { c.addFiles(files); });
      /* cleared so the same file can be picked again after it
         has been removed from the list */
      e.target.value = '';
    });

    drop.addEventListener('dragover', function(e) {
      e.preventDefault();
      e.stopPropagation();
      if (!c.dragging) $scope.$apply(function() { c.dragging = true; });
    });

    drop.addEventListener('dragleave', function(e) {
      e.preventDefault();
      e.stopPropagation();
      if (c.dragging) $scope.$apply(function() { c.dragging = false; });
    });

    drop.addEventListener('drop', function(e) {
      e.preventDefault();
      e.stopPropagation();
      var files = (e.dataTransfer && e.dataTransfer.files) ? e.dataTransfer.files : null;
      $scope.$apply(function() {
        c.dragging = false;
        if (files && files.length) c.addFiles(files);
      });
    });
  }

  /* either form opening is the cue to wire its dropzone */
  $scope.$watch(function() { return c.form; }, function(which) {
    if (which === 'report' || which === 'change') $timeout(bindDropzone);
  });


  function toBase64(files) {
    var jobs = [];

    angular.forEach(files, function(file) {
      jobs.push(new Promise(function(resolve, reject) {
        var reader = new FileReader();

        reader.onload = function(e) {
          try {
            var parts = ('' + e.target.result).split(',');
            resolve({
              name: file.name,
              type: file.type || 'application/octet-stream',
              size: file.size,
              data: parts.length > 1 ? parts[1] : parts[0]
            });
          } catch (err) { reject(err); }
        };

        reader.onerror = function() { reject('read failed: ' + file.name); };
        reader.readAsDataURL(file);
      }));
    });

    return Promise.all(jobs);
  }


  /* =====================================================
     SUBMIT
     ===================================================== */

  function post(payload, okMessage) {
    c.server.get(payload).then(function(r) {
      c.saving = false;
      var resp = (r && r.data) ? r.data : {};

      if (resp.success) {
        c.form = '';
        c.errors = {};
        c.files = [];
        spModal.open({
          title: okMessage,
          /* the server says so when the record saved but the
             files did not, and that is worth showing */
          message: resp.error || '',
          buttons: [{ label: c.data.t.ok, primary: true }]
        });
        /* the reload brings back the new row, the recounted
           tiles and the repainted heat map in one pass */
        c.server.update();
      } else {
        spModal.open({
          title: c.data.t.failed,
          message: resp.error || '',
          buttons: [{ label: c.data.t.ok, primary: true }]
        });
      }
    }, function() {
      c.saving = false;
      spModal.open({
        title: c.data.t.failed,
        message: '',
        buttons: [{ label: c.data.t.ok, primary: true }]
      });
    });
  }

  /* the files are read before the payload goes, so a failed
     read never leaves a record with half its evidence */
  function send(payload, okMessage) {
    c.saving = true;

    if (!c.files.length) {
      post(payload, okMessage);
      return;
    }

    toBase64(c.files).then(function(files) {
      $timeout(function() {
        payload.attachments = files;
        post(payload, okMessage);
      });
    }, function() {
      $timeout(function() {
        c.saving = false;
        spModal.open({
          title: c.data.t.fileErrTitle,
          message: c.data.t.fileErrText,
          buttons: [{ label: c.data.t.ok, primary: true }]
        });
      });
    });
  }

  c.submitReport = function() {
    if (c.saving) return;

    c.errors = {};

    if (empty(c.report.project))           c.errors.project = c.data.t.eProject;
    if (empty(c.report.status_date))       c.errors.status_date = c.data.t.eDate;
    if (empty(c.report.report_status))     c.errors.report_status = c.data.t.eType;
    if (empty(c.report.overall_health))    c.errors.overall_health = c.data.t.eHealth;
    if (empty(c.report.executive_summary)) c.errors.executive_summary = c.data.t.eSummary;

    var pct = c.report.percent_complete;
    if (pct === null || pct === '' || pct < 0 || pct > 100) {
      c.errors.percent_complete = c.data.t.ePercent;
    }

    if (c.errorCount()) return;

    var p = angular.copy(c.report);
    p.action = 'submit_report';
    send(p, c.data.t.savedReport);
  };

  c.submitChange = function() {
    if (c.saving) return;

    c.errors = {};

    if (empty(c.change.project))           c.errors.project = c.data.t.eProject;
    if (empty(c.change.title))             c.errors.title = c.data.t.fTitle + ' ' + c.data.t.eRequired;
    if (empty(c.change.category))          c.errors.category = c.data.t.fCategory + ' ' + c.data.t.eRequired;
    if (empty(c.change.priority))          c.errors.priority = c.data.t.fPriority + ' ' + c.data.t.eRequired;
    if (empty(c.change.impact))            c.errors.impact = c.data.t.fImpact + ' ' + c.data.t.eRequired;
    if (empty(c.change.proposed_change))   c.errors.proposed_change = c.data.t.fProposed + ' ' + c.data.t.eRequired;
    if (empty(c.change.reason_for_change)) c.errors.reason_for_change = c.data.t.fReason + ' ' + c.data.t.eRequired;

    if (c.errorCount()) return;

    var q = angular.copy(c.change);
    q.action = 'submit_change';
    send(q, c.data.t.savedChange);
  };

}

sp_widget.css:
/* =========================================================
   GATENOW · REPORTS AND CHANGE REQUESTS
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   THE HEAT MAP
   Coloured by the health each report carried, not by whether
   one was filed. A grid that only says "something arrived" is a
   grid of green squares telling an applicant nothing they did
   not already know. Colouring it by health means a run of amber
   across one row is visible from across the room, which is the
   entire point of putting it on a page.

   Empty cells are a hairline outline rather than a grey fill,
   so a missing report reads as absence rather than as a fourth
   status.

   TYPE
     tile      30  700  tabular   headline figures
     title     26  700  -0.03em   page title
     panel     15  600  -0.014em  panel headings
     data      14  600  tabular   dates and references
     label     11  600   0.14em   uppercase small caps
   ========================================================= */

/* ---------- overflow overrides ---------- */

.panel,
.panel-body,
.sp-widget { overflow: visible !important; }

.gn-layout { overflow: visible !important; }

/* The column holds the rail and lets it decide how wide to be.
   It used to carry a width through an inline ng-style, which is
   what put 140px of the rail on top of this page: the column
   reserved 96 while the rail draws 236.

   The transition moved to the rail, which is the element that
   actually changes width. Animating a wrapper that never
   resized was doing nothing. */

.aw-sidebar {
  flex: 0 0 auto;
  position: sticky;
  top: 0;
  height: 100vh;
  z-index: 10; /* Ensures sidebar tooltips stay above the scrolling dashboard */
  overflow: visible; /* Kept visible to prevent tooltip clipping as noted in your comments */
}

/* ---------- typeface ---------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- ink ---------- */
$c-navy:   #0a2540;
$c-ink-2:  rgba(10, 37, 64, 0.72);
$c-ink-3:  rgba(10, 37, 64, 0.54);
$c-ink-4:  rgba(10, 37, 64, 0.38);
$c-line:   rgba(10, 37, 64, 0.10);
$c-line-2: rgba(10, 37, 64, 0.06);
$c-tint:   rgba(10, 37, 64, 0.03);

/* ---------- accent ---------- */
$c-blue:    #1560e0;
$c-blue-dk: #0f4cbb;
$c-blue-1:  rgba(21, 96, 224, 0.08);
$c-blue-2:  rgba(21, 96, 224, 0.16);

/* ---------- the platform's own RAG scale ---------- */
$c-green:   #1f8a63;
$c-green-1: rgba(31, 138, 99, 0.12);
$c-amber:   #E39944;
$c-amber-1: rgba(227, 153, 68, 0.12);
$c-red:     #b8394a;
$c-red-1:   rgba(184, 57, 74, 0.10);
$c-red-2:   rgba(184, 57, 74, 0.28);

$c-white: #ffffff;
$c-page:  #f4f6fb;
$c-ease:  cubic-bezier(0.45, 0.05, 0.25, 1);

$c-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   PAGE
   ========================================================= */

.gn-layout {
  display: flex;
  align-items: stretch;
  min-height: 100vh;
  background: $c-page;
  font-family: $c-font;
}

/* Without min-width: 0 a flex child refuses to shrink below its
   own content width, and slides under the rail rather than
   narrowing. That is the usual cause of a stubborn overlap once
   the widths are right. */
.grc {
  flex: 1;
  min-width: 0;
  overflow: visible;
}

.grc {
  min-height: 100vh;
  padding: 28px 36px 68px;
  background: $c-page;
  font-family: $c-font;
  color: $c-navy;
  -webkit-font-smoothing: antialiased;
}

.grc *,
.grc *::before,
.grc *::after { box-sizing: border-box; }

.grc-right { text-align: right; }


/* =========================================================
   HEADER
   ========================================================= */

.grc-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px 24px;
  margin-bottom: 22px;
}

.grc-top__lead { min-width: 0; }

.grc .grc-top__title {
  margin: 0;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: $c-navy;
}

.grc .grc-top__sub {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 7px 0 0;
  font-size: 13.5px;
  color: $c-ink-3;
}

.grc-live {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: $c-green;
  box-shadow: 0 0 0 3px $c-green-1;
  flex-shrink: 0;
}

.grc-top__right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.grc-search {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 330px;
  height: 42px;
  padding: 0 12px 0 14px;
  margin: 0;
  border: 1px solid $c-line;
  border-radius: 11px;
  background: $c-white;
  font-weight: 400;
  transition: border-color 0.4s $c-ease, box-shadow 0.4s $c-ease;
}

.grc-search:focus-within {
  border-color: rgba(21, 96, 224, 0.45);
  box-shadow: 0 0 0 3px $c-blue-1;
}

.grc-search__icon {
  font-size: 13px;
  color: $c-ink-4;
  flex-shrink: 0;
}

.grc-search__field {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  font-family: inherit;
  font-size: 14px;
  color: $c-navy;
}

.grc-search__field::placeholder { color: $c-ink-4; }

.grc-search__clear {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: $c-tint;
  color: $c-ink-3;
  font-size: 10px;
  cursor: pointer;
  flex-shrink: 0;
}

.grc-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: $c-blue;
  color: $c-white;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.03em;
  flex-shrink: 0;
  box-shadow: 0 6px 16px rgba(21, 96, 224, 0.28);
}


/* =========================================================
   NOTHING YET
   ========================================================= */

.grc-blank {
  max-width: 520px;
  margin: 70px auto;
  padding: 52px 34px 46px;
  border: 1px solid $c-line;
  border-radius: 18px;
  background: $c-white;
  text-align: center;
}

.grc-blank__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  margin: 0 auto 20px;
  border-radius: 50%;
  background: $c-blue-1;
  color: $c-blue;
  font-size: 22px;
}

.grc .grc-blank__title {
  margin: 0;
  font-size: 21px;
  font-weight: 700;
  letter-spacing: -0.024em;
  color: $c-navy;
}

.grc .grc-blank__text {
  max-width: 46ch;
  margin: 11px auto 0;
  font-size: 15px;
  line-height: 1.64;
  color: $c-ink-3;
}


/* =========================================================
   TILES
   ========================================================= */

.grc-tiles {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 16px;
}

.grc-tile {
  position: relative;
  padding: 20px 22px 22px;
  border: 1px solid $c-line;
  border-radius: 16px;
  background: $c-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
  transition: transform 0.5s $c-ease, box-shadow 0.5s $c-ease;
}

.grc-tile:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 32px rgba(10, 37, 64, 0.08);
}

.grc-tile__rule {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 2px;
  background: $c-blue-2;
  transform-origin: left center;
}

.grc-tile.is-alert .grc-tile__rule { background: rgba(227, 153, 68, 0.34); }

.grc .grc-tile__label {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $c-ink-4;
}

.grc .grc-tile__value {
  margin: 12px 0 0;
  font-size: 30px;
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.034em;
  font-variant-numeric: tabular-nums;
  color: $c-navy;
}

.grc .grc-tile__note {
  margin: 8px 0 0;
  font-size: 12.5px;
  line-height: 1.5;
  color: $c-ink-3;
}

.grc-tile.is-alert .grc-tile__note {
 color: $c-ink-3;
  font-weight: 400;
}


/* =========================================================
   PANELS
   ========================================================= */

.grc-panel {
  padding: 22px 24px 24px;
  margin-bottom: 16px;
  border: 1px solid $c-line;
  border-radius: 16px;
  background: $c-white;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
}

.grc-panels {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
  gap: 16px;
  margin-bottom: 16px;
}

.grc-panels .grc-panel { margin-bottom: 0; }

.grc-panel__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px 24px;
  margin-bottom: 20px;
}

.grc .grc-panel__title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.014em;
  color: $c-navy;
}

.grc .grc-panel__hint {
  margin: 5px 0 0;
  font-size: 12.5px;
  color: $c-ink-4;
}

.grc .grc-panel__empty {
  margin: 0;
  padding: 26px 0 6px;
  font-size: 13.5px;
  color: $c-ink-4;
}

.grc .grc-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.grc .grc-legend li {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: $c-ink-3;
}

.grc-legend__box {
  width: 13px;
  height: 13px;
  border-radius: 4px;
  flex-shrink: 0;
}


/* =========================================================
   HEAT MAP
   ========================================================= */

.grc-panel--heat { overflow-x: auto; }

.grc-heat {
  display: grid;
  gap: 6px;
}

.grc-heat__row {
  display: grid;
  grid-template-columns: 220px repeat(6, minmax(0, 1fr));
  align-items: center;
  gap: 6px;
}

.grc-heat__row--head { margin-bottom: 2px; }

.grc-heat__name {
  min-width: 0;
  padding-right: 14px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 13.5px;
  font-weight: 500;
  color: $c-navy;
}

.grc-heat__month {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  text-align: center;
  color: $c-ink-4;
}

.grc-heat__cellwrap { min-width: 0; }

.grc-cell {
  display: block;
  height: 34px;
  border-radius: 7px;
  transition: transform 0.35s $c-ease, box-shadow 0.35s $c-ease;
}

.grc-cell:hover {
  transform: scale(1.06);
  box-shadow: 0 6px 16px rgba(10, 37, 64, 0.14);
}

.grc-cell--green { background: $c-green; }
.grc-cell--amber { background: $c-amber; }
.grc-cell--red   { background: $c-red; }

/* absence, drawn as an outline rather than a fourth colour */
.grc-cell--none {
  background: transparent;
  box-shadow: inset 0 0 0 1px $c-line;
}

.grc-legend__box.grc-cell--none {
  height: 13px;
  box-shadow: inset 0 0 0 1px $c-line;
}


/* =========================================================
   REPORTS FILED EACH MONTH

   A count over time, drawn the same way as claimed against
   paid on the reimbursements page, so the two pages read as
   one product.

   COLOUR, LIGHTLY
   The tall bar is the accent blue at 70 percent, the short one
   a muted amber. Nothing here is at full saturation, because
   the chart is a count rather than an alarm, and a light bar is
   still perfectly legible against a white plot.
   ========================================================= */

.grc-chart {
  display: flex;
  gap: 14px;
}

.grc-chart__axis {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 176px;
  flex-shrink: 0;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  color: $c-ink-4;
  text-align: right;
}

.grc-chart__plot {
  position: relative;
  flex: 1;
  min-width: 0;
  height: 176px;
}

.grc-chart__line {
  position: absolute;
  right: 0;
  left: 0;
  top: 0;
  height: 1px;
  background: $c-line-2;
}

.grc-chart__line--mid  { top: 50%; }
.grc-chart__line--base { top: auto; bottom: 0; background: $c-line; }

.grc-chart__cols {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
}

.grc-col {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  height: 100%;
  min-width: 0;
  flex: 1;
}

.grc-col__pair {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 5px;
  width: 100%;
  height: 100%;
  padding-bottom: 24px;
}

/* a min-height so a month with one report is a visible mark
   rather than a gap the reader has to interpret */
.grc-col__bar {
  display: block;
  width: 17px;
  min-height: 2px;
  border-radius: 4px 4px 0 0;
  transform-origin: bottom center;
}

.grc-col__bar--all { background: rgba(21, 96, 224, 0.7); }
/* Set to solid $c-amber so it perfectly matches the heat map */
.grc-col__bar--bad { background: $c-amber; }

.grc-col__label {
  position: absolute;
  bottom: 0;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: $c-ink-4;
}

.grc .grc-key {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.grc .grc-key li {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: $c-ink-3;
}

.grc-key__box {
  width: 12px;
  height: 12px;
  border-radius: 4px;
  flex-shrink: 0;
}

.grc-key__box--all { background: rgba(21, 96, 224, 0.7); }
.grc-key__box--bad { background: $c-amber; }


/* =========================================================
   COUNT BARS

   Horizontal, one row per thing, measured against the largest
   of them rather than as a share of a total. The share is what
   made every bar full width when there was only one report to
   divide between them.

   One colour, lightened along the run, so the rows rank without
   four hues arguing about it.
   ========================================================= */

.grc-rows {
  display: grid;
  gap: 11px;
}

.grc-row2 {
  display: grid;
  grid-template-columns: 148px minmax(0, 1fr) 52px;
  align-items: center;
  gap: 14px;
}

.grc-row2__label {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 13px;
  color: $c-ink-2;
}

.grc-row2__track {
  display: block;
  height: 9px;
  border-radius: 999px;
  background: $c-tint;
  overflow: hidden;
}

.grc-row2__fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: rgba(21, 96, 224, 0.7);
  transform-origin: left center;
}

/* the pressure rows lighten down the ranking */
.grc-row2--n1 .grc-row2__fill { background: rgba(227, 153, 68, 0.8); }
.grc-row2--n2 .grc-row2__fill { background: rgba(227, 153, 68, 0.58); }
.grc-row2--n3 .grc-row2__fill { background: rgba(227, 153, 68, 0.4); }
.grc-row2--n4 .grc-row2__fill { background: rgba(227, 153, 68, 0.28); }

/* the outcome rows keep their meaning, at the same weight */
.grc-row2--wait .grc-row2__fill  { background: rgba(21, 96, 224, 0.7); }
.grc-row2--good .grc-row2__fill  { background: rgba(31, 138, 99, 0.62); }
.grc-row2--bad .grc-row2__fill   { background: rgba(184, 57, 74, 0.58); }
.grc-row2--draft .grc-row2__fill { background: rgba(10, 37, 64, 0.2); }

.grc-row2__value {
  text-align: right;
  font-size: 13.5px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: $c-navy;
}

/* a row with nothing in it says so, and steps back */
.grc-row2.is-clean .grc-row2__label { color: $c-ink-4; }

.grc-row2__none {
  font-size: 12px;
  font-weight: 400;
  color: $c-ink-4;
}

.grc .grc-note {
  margin: 16px 0 0;
  padding-top: 14px;
  border-top: 1px solid $c-line-2;
  font-size: 12.5px;
  color: $c-ink-4;
}

.grc .grc-sub2 {
  margin: 26px 0 14px;
  padding-top: 20px;
  border-top: 1px solid $c-line;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $c-blue;
}

.grc .grc-cats {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin: 14px 0 0;
  padding: 0;
  list-style: none;
}

.grc .grc-cats li {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  padding: 6px 12px;
  border: 1px solid $c-line;
  border-radius: 999px;
  font-size: 12.5px;
  color: $c-ink-3;
}

.grc-cats__name { color: $c-ink-2; }

.grc-cats__n {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: $c-navy;
}


/* =========================================================
   STILL TO REPORT
   ========================================================= */

.grc-due {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px 24px;
  padding: 18px 22px;
  margin-bottom: 16px;
  border: 1px solid rgba(227, 153, 68, 0.26);
  border-left: 3px solid $c-amber;
  border-radius: 14px;
  background: $c-amber-1;
}

.grc-due__lead { min-width: 0; }

.grc .grc-due__title {
  margin: 0 0 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $c-amber;
}

.grc .grc-due__list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.grc .grc-due__list li {
  padding: 4px 11px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.7);
  font-size: 13px;
  font-weight: 500;
  color: $c-navy;
}


/* =========================================================
   TABLE
   ========================================================= */

.grc-block {
  border: 1px solid $c-line;
  border-radius: 16px;
  background: $c-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
}

.grc-block__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px 24px;
  padding: 20px 24px;
}

.grc-tabs {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px;
  border: 1px solid $c-line;
  border-radius: 11px;
  background: $c-page;
}

.grc-tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 34px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: $c-ink-3;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: background 0.4s $c-ease, color 0.4s $c-ease, border-color 0.4s $c-ease;
}

.grc-tab:hover { color: $c-navy; }

.grc-tab.is-on {
  background: $c-white;
  border-color: $c-line;
  color: $c-navy;
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.06);
}

.grc-tab__count {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: $c-ink-4;
}

.grc-block__acts {
  display: flex;
  align-items: center;
  gap: 8px;
}

.grc-table { min-width: 0; }

.grc-table__head,
.grc-row {
  display: grid;
  align-items: center;
  gap: 0 22px;
  padding: 0 24px;
}

.grc-table--reports .grc-table__head,
.grc-table--reports .grc-row {
  grid-template-columns: 128px minmax(0, 1fr) 148px 124px 118px 96px;
}

.grc-table--changes .grc-table__head,
.grc-table--changes .grc-row {
  grid-template-columns: 152px minmax(0, 1fr) 124px 124px 150px 96px;
}

.grc-table__head {
  height: 42px;
  border-top: 1px solid $c-line-2;
  border-bottom: 1px solid $c-line-2;
  background: rgba(10, 37, 64, 0.015);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: $c-ink-4;
}

.grc-table__head > .grc-right,
.grc-row > .grc-right {
  text-align: right;
  justify-self: end;
}

.grc-row {
  min-height: 64px;
  padding-top: 13px;
  padding-bottom: 13px;
  border-bottom: 1px solid $c-line-2;
  font-size: 14px;
  color: $c-ink-2;
  transition: background 0.4s $c-ease;
}

.grc-row:last-child { border-bottom: 0; }

.grc-row:hover { background: rgba(21, 96, 224, 0.025); }

.grc-cell--ref {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $c-navy;
}

.grc-cell--name {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: $c-navy;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.grc-cell__top,
.grc-cell__sub {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.grc-cell__sub {
  font-size: 12.5px;
  font-weight: 400;
  color: $c-ink-4;
}

.grc-cell--muted { color: $c-ink-3; }

.grc-cell--date {
  font-variant-numeric: tabular-nums;
  color: $c-ink-3;
}

.grc .grc-empty {
  margin: 0;
  padding: 52px 24px;
  text-align: center;
  font-size: 14px;
  color: $c-ink-4;
}


/* ---------- rag text and pills ---------- */

.grc-rag {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 13px;
  font-weight: 600;
}

.grc-rag__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.grc-rag--green { color: $c-green; }
.grc-rag--amber { color: $c-amber; }
.grc-rag--red   { color: $c-red; }
.grc-rag--none  { color: $c-ink-4; font-weight: 400; }

.grc-rag--green .grc-rag__dot { background: $c-green; }
.grc-rag--amber .grc-rag__dot { background: $c-amber; }
.grc-rag--red .grc-rag__dot   { background: $c-red; }
.grc-rag--none .grc-rag__dot  {
  background: transparent;
  box-shadow: inset 0 0 0 1.5px rgba(10, 37, 64, 0.24);
}

.grc-pill {
  display: inline-flex;
  padding: 4px 11px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
}

.grc-pill--good  { background: $c-green-1; color: $c-green; }
.grc-pill--wait  { background: $c-blue-1;  color: $c-blue-dk; }
.grc-pill--bad   { background: $c-red-1;   color: $c-red; }
.grc-pill--draft { background: $c-tint;    color: $c-ink-3; }


/* =========================================================
   BUTTONS
   ========================================================= */

.grc-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 40px;
  padding: 0 17px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.4s $c-ease, border-color 0.4s $c-ease, color 0.4s $c-ease;
}

.grc-btn--sm {
  height: 34px;
  padding: 0 14px;
  font-size: 13px;
}

.grc-btn--primary {
  background: $c-blue;
  border-color: $c-blue;
  color: $c-white;
}

.grc-btn--primary:hover,
.grc-btn--primary:focus {
  background: $c-blue-dk;
  border-color: $c-blue-dk;
  color: $c-white;
}

.grc-btn--ghost {
  border-color: $c-line;
  color: $c-ink-2;
}

.grc-btn--ghost:hover,
.grc-btn--ghost:focus {
  border-color: $c-blue-2;
  color: $c-blue-dk;
}

.grc-btn:disabled {
  opacity: 0.5;
  cursor: default;
}

.grc-btn:focus-visible,
.grc-tab:focus-visible,
.grc-search__clear:focus-visible {
  outline: 2px solid $c-blue;
  outline-offset: 2px;
}


/* =========================================================
   MODAL
   ========================================================= */

.grc-modal {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1050;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 40px 20px;
  overflow-y: auto;
  background: rgba(10, 37, 64, 0.42);
  -webkit-backdrop-filter: blur(3px);
  backdrop-filter: blur(3px);
}

.grc-modal__panel {
  width: 100%;
  max-width: 720px;
  border-radius: 18px;
  background: $c-white;
  box-shadow: 0 30px 80px rgba(10, 37, 64, 0.3);
  overflow: hidden;
}

.grc-modal__panel--wide { max-width: 900px; }

.grc-modal__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 24px 26px 20px;
  border-bottom: 1px solid $c-line-2;
}

.grc-modal__lead { min-width: 0; }

.grc-modal__ref {
  display: block;
  margin-bottom: 7px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: $c-ink-4;
}

.grc .grc-modal__title {
  margin: 0;
  font-size: 21px;
  font-weight: 700;
  line-height: 1.26;
  letter-spacing: -0.026em;
  color: $c-navy;
}

.grc .grc-modal__hint,
.grc-modal__meta {
  display: block;
  margin: 7px 0 0;
  font-size: 13px;
  color: $c-ink-4;
}

.grc-modal__x {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border: 1px solid $c-line;
  border-radius: 10px;
  background: transparent;
  color: $c-ink-3;
  font-size: 13px;
  cursor: pointer;
  transition: border-color 0.4s $c-ease, color 0.4s $c-ease;
}

.grc-modal__x:hover {
  border-color: $c-blue-2;
  color: $c-blue-dk;
}

.grc-modal__body {
  max-height: 62vh;
  padding: 22px 26px;
  overflow-y: auto;
}

.grc-modal__foot {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 16px 26px;
  border-top: 1px solid $c-line-2;
  background: $c-page;
}


/* ---------- form ---------- */

.grc-errors {
  padding: 14px 17px 15px;
  margin-bottom: 20px;
  border: 1px solid $c-red-2;
  border-radius: 12px;
  background: $c-red-1;
}

.grc .grc-errors ul {
  margin: 0;
  padding-left: 18px;
  font-size: 13.5px;
  line-height: 1.7;
  color: $c-red;
}

.grc-fields {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 18px 16px;
}

.grc-field--full    { grid-column: span 12; }
.grc-field--half    { grid-column: span 6; }
.grc-field--third   { grid-column: span 4; }
.grc-field--quarter { grid-column: span 3; }

.grc-field { min-width: 0; }

.grc-field label {
  display: block;
  margin-bottom: 7px;
  font-size: 13px;
  font-weight: 600;
  color: $c-navy;
}

.grc-field input[type="text"],
.grc-field input[type="number"],
.grc-field input[type="date"],
.grc-field select,
.grc-field textarea,
.grc-rate input,
.grc-rate select,
.grc-rate textarea {
  width: 100%;
  min-height: 44px;
  padding: 10px 14px;
  border: 1px solid $c-line;
  border-radius: 10px;
  background: $c-white;
  font-family: inherit;
  font-size: 14.5px;
  line-height: 1.5;
  color: $c-navy;
  transition: border-color 0.35s $c-ease, box-shadow 0.35s $c-ease;
}

.grc-field textarea,
.grc-rate textarea {
  min-height: auto;
  resize: vertical;
  line-height: 1.65;
}

.grc-field input:focus,
.grc-field select:focus,
.grc-field textarea:focus,
.grc-rate select:focus,
.grc-rate textarea:focus {
  outline: 0;
  border-color: rgba(21, 96, 224, 0.5);
  box-shadow: 0 0 0 3px $c-blue-1;
}

/* the error state is a border and a message, not a red field.
   Filling the input red makes the value hard to read at exactly
   the moment you need to fix it. */
.grc-field input.has-error,
.grc-field select.has-error,
.grc-field textarea.has-error {
  border-color: $c-red-2;
  background: $c-red-1;
}

.grc .grc-sub {
  grid-column: span 12;
  margin: 8px 0 -6px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $c-blue;
}

.grc-pick {
  position: relative;
  display: block;
}

.grc-pick select {
  appearance: none;
  -webkit-appearance: none;
  padding-right: 38px;
  cursor: pointer;
}

.grc-pick i {
  position: absolute;
  top: 50%;
  right: 14px;
  margin-top: -7px;
  font-size: 14px;
  color: $c-ink-4;
  pointer-events: none;
}

/* rating and its comment on one line, which is how the platform
   form groups them */
.grc-rate {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 16px;
  align-items: start;
}

.grc-rate__pick { min-width: 0; }
.grc-rate__note { min-width: 0; }

.grc-rate label {
  display: block;
  margin-bottom: 7px;
  font-size: 13px;
  font-weight: 600;
  color: $c-navy;
}


/* ---------- upload ---------- */

.grc-drop {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 30px 22px 26px;
  border: 1.5px dashed $c-line;
  border-radius: 14px;
  background: $c-tint;
  text-align: center;
  transition: border-color 0.4s $c-ease, background 0.4s $c-ease;
}

/* The native input is hidden rather than removed, because
   display:none stops some browsers firing click() on a file
   input programmatically and that would kill the button.

   The element also carries these rules inline, since a portal
   theme styles input[type=file] and would otherwise render the
   browser's own control above the drop zone. This rule is the
   belt to that inline brace. */
.grc .grc-drop input.grc-file-input,
.grc-file-input {
  position: absolute;
  left: 0;
  top: 0;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: 0;
  border: 0;
  opacity: 0;
  overflow: hidden;
  pointer-events: none;
  white-space: nowrap;
}

.grc-drop.is-over {
  border-color: $c-blue;
  background: $c-blue-1;
}

.grc-drop__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  margin-bottom: 13px;
  border-radius: 50%;
  background: $c-white;
  border: 1px solid $c-line;
  color: $c-blue;
  font-size: 16px;
}

.grc .grc-drop__title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.014em;
  color: $c-navy;
}

.grc .grc-drop__text {
  margin: 5px 0 14px;
  font-size: 13px;
  color: $c-ink-3;
}

.grc .grc-drop__note {
  margin: 9px 0 0;
  font-size: 12px;
  color: $c-ink-4;
}

.grc .grc-files {
  display: grid;
  gap: 8px;
  margin: 14px 0 0;
  padding: 0;
  list-style: none;
}

.grc-file {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 13px;
  border: 1px solid $c-line;
  border-radius: 11px;
  background: $c-white;
}

.grc-file__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 9px;
  background: $c-blue-1;
  color: $c-blue;
  font-size: 13px;
  flex-shrink: 0;
}

.grc-file__body {
  flex: 1;
  min-width: 0;
}

.grc-file__name {
  display: block;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 13.5px;
  font-weight: 500;
  color: $c-navy;
}

.grc-file__size {
  display: block;
  margin-top: 2px;
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
  color: $c-ink-4;
}

.grc-file__x {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: $c-ink-4;
  font-size: 11px;
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.35s $c-ease, color 0.35s $c-ease;
}

.grc-file__x:hover {
  background: $c-red-1;
  color: $c-red;
}


/* ---------- report detail ---------- */

.grc-ragrid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 8px;
}

.grc-ragrid__item {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 11px 12px;
  border-radius: 9px;
  background: $c-tint;
  border-left: 3px solid transparent;
}

.grc-ragrid__item--green { background: $c-green-1; border-left-color: $c-green; }
.grc-ragrid__item--amber { background: $c-amber-1; border-left-color: $c-amber; }
.grc-ragrid__item--red   { background: $c-red-1;   border-left-color: $c-red; }

.grc-ragrid__label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: $c-ink-4;
}

.grc-ragrid__value {
  font-size: 13px;
  font-weight: 600;
  color: $c-navy;
}

.grc .grc-kvs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 30px;
  margin: 0 0 4px;
  padding: 0;
}

.grc-kv { min-width: 0; }

.grc .grc-kv dt {
  margin: 0 0 4px;
  font-size: 12px;
  color: $c-ink-4;
}

.grc .grc-kv dd {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: $c-navy;
}

.grc .grc-kv dd.is-blank {
  font-weight: 400;
  font-style: italic;
  color: $c-ink-4;
}

.grc-prose { margin-top: 20px; }

.grc .grc-prose__label {
  margin: 0 0 6px;
  font-size: 12px;
  color: $c-ink-4;
}

/* the line breaks the author typed are kept */
.grc .grc-prose__text {
  margin: 0;
  max-width: 74ch;
  font-size: 14.5px;
  line-height: 1.7;
  color: $c-ink-2;
  white-space: pre-line;
}


/* =========================================================
   MOTION
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes grcRise {
    from { opacity: 0; transform: translateY(14px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  @keyframes grcDrawX {
    from { transform: scaleX(0); }
    to   { transform: scaleX(1); }
  }

  @keyframes grcFade {
    from { opacity: 0; }
    to   { opacity: 1; }
  }

  @keyframes grcPanelIn {
    from { opacity: 0; transform: translateY(16px) scale(0.99); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
  }

  .grc-top  { animation: grcRise 0.6s $c-ease backwards; }
  .grc-tile { animation: grcRise 0.62s $c-ease backwards; }

  .grc-tile--due     { animation-delay: 0.06s; }
  .grc-tile--reports { animation-delay: 0.12s; }
  .grc-tile--health  { animation-delay: 0.18s; }
  .grc-tile--changes { animation-delay: 0.24s; }

  .grc-tile__rule { animation: grcDrawX 0.7s $c-ease 0.3s backwards; }

  .grc-panel { animation: grcRise 0.62s $c-ease 0.28s backwards; }
  .grc-due   { animation: grcRise 0.6s $c-ease 0.34s backwards; }
  .grc-block { animation: grcRise 0.62s $c-ease 0.38s backwards; }

  /* the heat map fills in row by row */
  .grc-heat__row { animation: grcFade 0.5s $c-ease backwards; }

  .grc-heat__row--n1 { animation-delay: 0.38s; }
  .grc-heat__row--n2 { animation-delay: 0.44s; }
  .grc-heat__row--n3 { animation-delay: 0.50s; }
  .grc-heat__row--n4 { animation-delay: 0.56s; }
  .grc-heat__row--n5 { animation-delay: 0.62s; }
  .grc-heat__row--n6 { animation-delay: 0.68s; }
  .grc-heat__row--n7 { animation-delay: 0.74s; }
  .grc-heat__row--n8 { animation-delay: 0.80s; }

  @keyframes grcGrowY {
    from { transform: scaleY(0); }
    to   { transform: scaleY(1); }
  }

  /* the columns grow from the axis */
  .grc-col__bar { animation: grcGrowY 0.6s $c-ease backwards; }

  .grc-col--n1 .grc-col__bar { animation-delay: 0.42s; }
  .grc-col--n2 .grc-col__bar { animation-delay: 0.48s; }
  .grc-col--n3 .grc-col__bar { animation-delay: 0.54s; }
  .grc-col--n4 .grc-col__bar { animation-delay: 0.60s; }
  .grc-col--n5 .grc-col__bar { animation-delay: 0.66s; }
  .grc-col--n6 .grc-col__bar { animation-delay: 0.72s; }

  /* the rows draw out from their left edge */
  .grc-row2__fill { animation: grcDrawX 0.7s $c-ease 0.46s backwards; }

  /* replays on every tab change, because ng-repeat rebuilds its
     nodes and the keyframe starts again with them */
  .grc-row { animation: grcRise 0.42s $c-ease backwards; }

  .grc-row--n1  { animation-delay: 0.02s; }
  .grc-row--n2  { animation-delay: 0.05s; }
  .grc-row--n3  { animation-delay: 0.08s; }
  .grc-row--n4  { animation-delay: 0.11s; }
  .grc-row--n5  { animation-delay: 0.14s; }
  .grc-row--n6  { animation-delay: 0.17s; }
  .grc-row--n7  { animation-delay: 0.20s; }
  .grc-row--n8  { animation-delay: 0.23s; }
  .grc-row--n9  { animation-delay: 0.26s; }
  .grc-row--n10 { animation-delay: 0.29s; }

  .grc-modal { animation: grcFade 0.28s $c-ease backwards; }
  .grc-modal__panel { animation: grcPanelIn 0.4s $c-ease 0.04s backwards; }
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1280px) {

  .grc { padding: 26px 24px 60px; }

  .grc-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }

  .grc-panels { grid-template-columns: minmax(0, 1fr); }

  .grc-heat__row { grid-template-columns: 170px repeat(6, minmax(0, 1fr)); }
}

@media (max-width: 980px) {

  .grc { padding: 22px 16px 52px; }

  .grc-top__right {
    width: 100%;
    order: 2;
  }

  .grc-search { width: 100%; }

  .grc-tiles { grid-template-columns: minmax(0, 1fr); }

  /* the heat map keeps its shape but drops the project column,
     which is the first thing to go when width runs out */
  .grc-heat__row { grid-template-columns: 116px repeat(6, minmax(0, 1fr)); }

  .grc-heat__name { font-size: 12.5px; }

  .grc-cell { height: 28px; }

  .grc-block__head { align-items: stretch; flex-direction: column; }

  .grc-block__acts .grc-btn { flex: 1; }

  /* six columns at this width leaves four of them two
     characters wide, so rows stack instead */
  .grc-table__head { display: none; }

  .grc-table--reports .grc-row,
  .grc-table--changes .grc-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
    padding: 16px 18px;
  }

  .grc-cell--name { grid-column: 1 / -1; }

  .grc-row > span::before {
    content: attr(data-label);
    display: block;
    margin-bottom: 4px;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: $c-ink-4;
  }

  .grc-cell--name::before { display: none; }

  .grc-row > .grc-right {
    text-align: left;
    justify-self: start;
  }

  .grc-ragrid { grid-template-columns: repeat(2, minmax(0, 1fr)); }


  .grc-rate { grid-template-columns: minmax(0, 1fr); }

  .grc-field--half,
  .grc-field--third,
  .grc-field--quarter { grid-column: span 12; }

  .grc .grc-kvs { grid-template-columns: minmax(0, 1fr); }

  .grc-modal { padding: 18px 12px; }
  .grc-modal__head { padding: 20px 18px 16px; }
  .grc-modal__body { padding: 18px; max-height: 66vh; }
  .grc-modal__foot { padding: 14px 18px; }
}

@media (prefers-reduced-motion: reduce) {
  .grc * { transition: none; }
  .grc-tile:hover { transform: none; }
  .grc-cell:hover { transform: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW · REPORTS AND CHANGE REQUESTS
     Service Portal widget · Server script

     One page for everything an applicant files against a live
     project: the monthly status report and the change request.
     Reading what has been filed, and filing the next one.

     Field names are taken from the two forms you sent:

       status report
         project, status_date, report_status, number,
         percent_complete, overall_health, executive_summary,
         comments, achievements_last_month,
         key_activities_next_month, schedule,
         comments_on_schedule, cost, comments_on_cost,
         resources, resource_comments, scope, comments_on_scope

       change request
         number, priority, impact, category, approval, project,
         title, proposed_change, reason_for_change

     The change table is x_enno_gatenow_request_change, which is
     the name your working script uses. A second candidate is
     tested in case the other spelling exists on your instance.

     GlideRecordSecure throughout, and both inserts verify the
     project belongs to the person signed in before writing.
     ========================================================= */

  var APPLICANT = 'x_enno_gatenow_service_applicants';
  var PROJECT   = 'x_enno_gatenow_project';
  var REPORT    = 'x_enno_gatenow_status_report';

  var CHANGE_TABLES = ['x_enno_gatenow_request_change', 'x_enno_gatenow_change_request'];

  var me = gs.getUserID();

  data.success = false;
  data.error   = '';
  data.savedAs = '';

  if (typeof input === 'undefined' || input === null) input = {};

  function opt(name, fallback) {
    var v = options[name];
    return (v === null || v === undefined || v === '') ? fallback : v.toString();
  }

  function param(key, dflt) {
    try {
      if (input && input[key] !== undefined && input[key] !== null) return input[key];
    } catch (e) { /* fall through */ }
    return dflt;
  }

  function lower(v) {
    return (v === null || v === undefined) ? '' : ('' + v).toLowerCase();
  }

  function toGDT(value) {
    if (!value) return null;
    var s = '' + value;
    if (s.length === 10) s += ' 00:00:00';
    try { return new GlideDateTime(s); } catch (e) { return null; }
  }

  function fmtDate(value) {
    var g = toGDT(value);
    if (!g) return '';
    try { return g.getDate().getByFormat('d MMM yyyy'); } catch (e) { return '' + value; }
  }

  function monthKey(value) {
    if (!value) return '';
    return ('' + value).substring(0, 7);
  }

  function cleanDate(v) {
    if (!v) return '';
    v = String(v);
    if (v.indexOf('T') > -1) return v.split('T')[0];
    var m = v.match(/\d{4}-\d{2}-\d{2}/);
    return m ? m[0] : v;
  }

  function pick(gr, names) {
    for (var i = 0; i < names.length; i++) {
      try {
        if (gr.isValidField(names[i])) {
          var v = gr.getValue(names[i]);
          if (v !== null && v !== undefined && v !== '') return v;
        }
      } catch (e) { /* next */ }
    }
    return '';
  }

  /* the long fields are HTML areas, and raw markup was leaking
     into the list views */
  function text(raw, cap) {
    if (!raw) return '';
    var s = ('' + raw)
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n\n')
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/[ \t]+/g, ' ')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
    if (cap && s.length > cap) s = s.substring(0, cap).replace(/\s+\S*$/, '') + '...';
    return s;
  }

  /* GlideRecord here rather than GlideRecordSecure, because
     isValid answers whether the table exists at all. No query
     runs and no data is read. Every actual read and write below
     goes through GlideRecordSecure. */
  /* Attachments arrive as base64 from the browser. A file with
     no data is skipped rather than written as an empty record. */
  function attach(table, sysId, files) {
    if (!files || !files.length) return 0;

    var rec = new GlideRecordSecure(table);
    if (!rec.get(sysId)) return 0;

    var done = 0;

    for (var i = 0; i < files.length; i++) {
      var f = files[i];
      if (!f || !f.data) continue;
      try {
        var id = new GlideSysAttachment().writeBase64(
          rec, f.name, f.type || 'application/octet-stream', f.data);
        if (id) done++;
        else gs.error('[Reports] attachment rejected: ' + f.name);
      } catch (e) {
        gs.error('[Reports] attachment failed on ' + f.name + ': ' + e.message);
      }
    }

    return done;
  }

  function firstValidTable(list) {
    for (var i = 0; i < list.length; i++) {
      try {
        var probe = new GlideRecordSecure(list[i]);
        if (probe.isValid()) return list[i];
      } catch (e) { /* next candidate */ }
    }
    return list[0];
  }

  var CHANGE = firstValidTable(CHANGE_TABLES);

  /* Green, Yellow and Red are the platform's own words, so they
     are kept rather than translated into something friendlier
     that would not match the record. */
  function rag(value) {
    var v = lower(value);
    if (v.indexOf('red') !== -1)    return { key: 'red',   label: gs.getMessage('Red') };
    if (v.indexOf('yellow') !== -1) return { key: 'amber', label: gs.getMessage('Yellow') };
    if (v.indexOf('green') !== -1)  return { key: 'green', label: gs.getMessage('Green') };
    return { key: 'none', label: gs.getMessage('Not set') };
  }


  /* ============================================================
     WHOSE PROJECTS
     ============================================================ */

  var projectIds = [];
  var projectName = {};

  data.projects = [];

  try {

    var applicantIds = [];
    var ap = new GlideRecordSecure(APPLICANT);
    ap.addQuery('user', me);
    ap.query();
    while (ap.next()) applicantIds.push(ap.getUniqueValue());

    if (applicantIds.length) {
      var pj = new GlideRecordSecure(PROJECT);
      pj.addQuery('applicant', 'IN', applicantIds.join(','));
      pj.orderBy('project_name');
      pj.query();

      while (pj.next()) {
        var pid = pj.getUniqueValue();
        var nm  = pick(pj, ['project_name', 'short_description']) || pj.getValue('number');

        projectIds.push(pid);
        projectName[pid] = nm;

        data.projects.push({
          sysId  : pid,
          number : pj.getValue('number'),
          name   : nm,
          phase  : pj.getDisplayValue('phase'),
          percent: parseInt(pj.getValue('percent_complete') || 0, 10) || 0,
          open   : lower(pj.getDisplayValue('phase')).indexOf('closed') === -1 &&
                   lower(pj.getDisplayValue('phase')).indexOf('cancel') === -1
        });
      }
    }

  } catch (e) {
    gs.error('[Reports] project lookup: ' + e.message);
  }

  function ownsProject(id) {
    return !!id && projectIds.indexOf('' + id) !== -1;
  }


  /* ============================================================
     WRITE ACTIONS
     ============================================================ */

  var action = String(param('action', ''));

  if (action === 'submit_report') {
    try {

      var rProject = String(param('project', ''));

      if (!ownsProject(rProject)) {
        data.error = gs.getMessage('That project is not one of yours.');
      } else {

        var rec = new GlideRecordSecure(REPORT);
        rec.initialize();

        rec.setValue('project', rProject);

        var sd = cleanDate(param('status_date', ''));
        if (sd) rec.setValue('status_date', sd);

        rec.setValue('report_status', param('report_status', ''));

        var pcRaw = param('percent_complete', '');
        if (pcRaw !== '' && pcRaw !== null) rec.setValue('percent_complete', pcRaw);

        rec.setValue('overall_health', param('overall_health', ''));
        rec.setValue('executive_summary', param('executive_summary', ''));
        rec.setValue('comments', param('comments', ''));
        rec.setValue('achievements_last_month', param('achievements_last_month', ''));
        rec.setValue('key_activities_next_month', param('key_activities_next_month', ''));

        rec.setValue('schedule', param('schedule', ''));
        rec.setValue('comments_on_schedule', param('comments_on_schedule', ''));
        rec.setValue('cost', param('cost', ''));
        rec.setValue('comments_on_cost', param('comments_on_cost', ''));
        rec.setValue('resources', param('resources', ''));
        rec.setValue('resource_comments', param('resource_comments', ''));
        rec.setValue('scope', param('scope', ''));
        rec.setValue('comments_on_scope', param('comments_on_scope', ''));

        var newReport = rec.insert();

        if (newReport) {

          var rFiles = param('attachments', []);
          var rDone  = attach(REPORT, newReport, rFiles);

          data.success = true;
          data.savedAs = 'report';
          data.attached = rDone;

          /* the record is in, but the applicant needs to know the
             documents are not */
          if (rFiles && rFiles.length && rDone === 0) {
            data.error = gs.getMessage('The report was filed but the attachments did not upload. Open the report and add them.');
          }

        } else {
          data.error = gs.getMessage('The report did not save. Nothing was lost, try again.');
        }
      }

    } catch (e) {
      gs.error('[Reports] report insert: ' + e.toString());
      data.error = gs.getMessage('Something went wrong saving the report.') + ' ' + e.message;
    }
  }

  if (action === 'submit_change') {
    try {

      var cProject = String(param('project', ''));

      if (!ownsProject(cProject)) {
        data.error = gs.getMessage('That project is not one of yours.');
      } else {

        var chg = new GlideRecordSecure(CHANGE);
        chg.initialize();

        chg.setValue('project', cProject);
        chg.setValue('title', param('title', ''));
        chg.setValue('category', param('category', ''));
        chg.setValue('priority', param('priority', ''));
        chg.setValue('impact', param('impact', ''));
        chg.setValue('proposed_change', param('proposed_change', ''));
        chg.setValue('reason_for_change', param('reason_for_change', ''));

        /* Submitting is the act of requesting. Leaving it at Not
           Yet Requested would file something nobody looks at. */
        chg.setValue('approval', 'Requested');

        var newChange = chg.insert();

        if (newChange) {

          var cFiles = param('attachments', []);
          var cDone  = attach(CHANGE, newChange, cFiles);

          data.success = true;
          data.savedAs = 'change';
          data.attached = cDone;

          if (cFiles && cFiles.length && cDone === 0) {
            data.error = gs.getMessage('The change request was raised but the attachments did not upload. Open it and add them.');
          }

        } else {
          data.error = gs.getMessage('The change request did not save. Nothing was lost, try again.');
        }
      }

    } catch (e) {
      gs.error('[Reports] change insert: ' + e.toString());
      data.error = gs.getMessage('Something went wrong saving the change request.') + ' ' + e.message;
    }
  }


  /* ============================================================
     CHROME
     ============================================================ */

  data.sideBar = $sp.getWidget(opt('sidebar_widget', 'sidebar'));

  var u = gs.getUser();
  var fn = u.getFirstName() || '';
  var ln = u.getLastName() || '';
  data.userInitials = (fn.charAt(0) + ln.charAt(0)).toUpperCase() ||
                      (u.getDisplayName() || 'U').substring(0, 2).toUpperCase();


  /* ============================================================
     READ
     ============================================================ */

  data.reports = [];
  data.changes = [];

  var MONTHS = 6;
  var monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  var monthKeys = [];
  data.months = [];

  for (var i = MONTHS - 1; i >= 0; i--) {
    var g = new GlideDateTime();
    g.addMonthsLocalTime(-i);
    var mi = g.getMonthLocalTime() - 1;
    var yr = g.getYearLocalTime();
    data.months.push(monthNames[mi]);
    monthKeys.push(yr + '-' + ('0' + (mi + 1)).slice(-2));
  }

  var thisMonth = monthKeys[monthKeys.length - 1];

  /* heat map cell per project per month */
  var grid = {};
  for (var gp = 0; gp < projectIds.length; gp++) {
    grid[projectIds[gp]] = {};
  }

  /* health counts per month, for the trend strip */
  var trend = {};
  for (var tk = 0; tk < monthKeys.length; tk++) {
    trend[monthKeys[tk]] = { green: 0, amber: 0, red: 0 };
  }

  var reportedThisMonth = {};

  var healthTotals = { green: 0, amber: 0, red: 0, none: 0 };

  /* Every dimension counted separately. Overall health alone
     says a project is amber; this says which of the four things
     made it amber, which is the part worth knowing. */
  var dims = {
    overall  : { green: 0, amber: 0, red: 0, none: 0 },
    schedule : { green: 0, amber: 0, red: 0, none: 0 },
    cost     : { green: 0, amber: 0, red: 0, none: 0 },
    resources: { green: 0, amber: 0, red: 0, none: 0 },
    scope    : { green: 0, amber: 0, red: 0, none: 0 }
  };

  try {

    if (projectIds.length) {

      var rp = new GlideRecordSecure(REPORT);
      rp.addQuery('project', 'IN', projectIds.join(','));
      rp.orderByDesc('status_date');
      rp.setLimit(300);
      rp.query();

      while (rp.next()) {

        var raw   = rp.getValue('status_date') || rp.getValue('sys_created_on');
        var mk    = monthKey(raw);
        var pid2  = rp.getValue('project');
        var h     = rag(rp.getValue('overall_health'));

        if (grid[pid2] && grid[pid2][mk] === undefined) {
          grid[pid2][mk] = h.key;
        }

        if (trend[mk]) {
          if (h.key === 'green') trend[mk].green++;
          else if (h.key === 'amber') trend[mk].amber++;
          else if (h.key === 'red') trend[mk].red++;
        }

        if (mk === thisMonth) reportedThisMonth[pid2] = true;


        healthTotals[h.key]++;

        var dSchedule  = rag(rp.getValue('schedule'));
        var dCost      = rag(rp.getValue('cost'));
        var dResources = rag(rp.getValue('resources'));
        var dScope     = rag(rp.getValue('scope'));

        dims.overall[h.key]++;
        dims.schedule[dSchedule.key]++;
        dims.cost[dCost.key]++;
        dims.resources[dResources.key]++;
        dims.scope[dScope.key]++;

        data.reports.push({
          sysId    : rp.getUniqueValue(),
          number   : rp.getValue('number'),
          projectId: pid2,
          project  : projectName[pid2] || '',
          period   : mk ? (monthNames[parseInt(mk.substring(5, 7), 10) - 1] + ' ' + mk.substring(0, 4)) : '',
          date     : fmtDate(raw),
          monthKey : mk,
          type     : rp.getDisplayValue('report_status'),
          percent  : parseInt(rp.getValue('percent_complete') || 0, 10) || 0,
          health   : h,
          schedule : dSchedule,
          cost     : dCost,
          resources: dResources,
          scope    : dScope,
          summary  : text(rp.getValue('executive_summary')),
          comments : text(rp.getValue('comments')),
          achieved : text(rp.getValue('achievements_last_month')),
          nextUp   : text(rp.getValue('key_activities_next_month')),
          cSchedule: text(rp.getValue('comments_on_schedule')),
          cCost    : text(rp.getValue('comments_on_cost')),
          cResource: text(rp.getValue('resource_comments')),
          cScope   : text(rp.getValue('comments_on_scope'))
        });
      }
    }

  } catch (e) {
    gs.error('[Reports] report read: ' + e.message);
  }

  /* ---------- change requests ---------- */
  var byCategory = {};
  var approval = { requested: 0, approved: 0, rejected: 0, notyet: 0 };

  try {

    if (projectIds.length) {

      var ch = new GlideRecordSecure(CHANGE);
      ch.addQuery('project', 'IN', projectIds.join(','));
      ch.orderByDesc('sys_created_on');
      ch.setLimit(300);
      ch.query();

      while (ch.next()) {

        var appr = lower(ch.getDisplayValue('approval'));

        var state = appr.indexOf('approved') !== -1 ? 'good'
                  : appr.indexOf('rejected') !== -1 ? 'bad'
                  : (appr.indexOf('requested') !== -1 && appr.indexOf('not yet') === -1) ? 'wait'
                  : 'draft';

        if (state === 'good')       approval.approved++;
        else if (state === 'bad')   approval.rejected++;
        else if (state === 'wait')  approval.requested++;
        else                        approval.notyet++;

        var cat = ch.getDisplayValue('category') || gs.getMessage('Uncategorised');

        if (!byCategory[cat]) {
          byCategory[cat] = { raised: 0, approved: 0, rejected: 0, waiting: 0 };
        }

        byCategory[cat].raised++;
        if (state === 'good')      byCategory[cat].approved++;
        else if (state === 'bad')  byCategory[cat].rejected++;
        else if (state === 'wait') byCategory[cat].waiting++;

        var cpid = ch.getValue('project');

        data.changes.push({
          sysId    : ch.getUniqueValue(),
          number   : ch.getValue('number'),
          projectId: cpid,
          project  : projectName[cpid] || '',
          title    : pick(ch, ['title', 'short_description']),
          category : ch.getDisplayValue('category'),
          priority : ch.getDisplayValue('priority'),
          impact   : ch.getDisplayValue('impact'),
          approval : ch.getDisplayValue('approval'),
          state    : state,
          proposed : text(ch.getValue('proposed_change')),
          reason   : text(ch.getValue('reason_for_change')),
          raised   : fmtDate(ch.getValue('sys_created_on'))
        });
      }
    }

  } catch (e) {
    gs.error('[Reports] change read: ' + e.message);
  }



  /* ============================================================
     ANALYTICS
     ============================================================ */

  /* ---------- heat map ----------
     Coloured by the health each report carried, not merely by
     whether one was filed. A grid of green squares that only
     means "something arrived" tells an applicant nothing they
     did not already know.
     ------------------------------------------------------- */
  data.heat = [];

  for (var hp = 0; hp < projectIds.length; hp++) {

    var hid = projectIds[hp];
    var hcells = [];

    for (var hm = 0; hm < monthKeys.length; hm++) {
      var hkey = monthKeys[hm];
      var hval = grid[hid] ? grid[hid][hkey] : null;

      hcells.push({
        key  : hval || 'none',
        month: data.months[hm],
        label: hval ? rag(hval === 'amber' ? 'yellow' : hval).label : gs.getMessage('No report')
      });
    }

    data.heat.push({
      sysId: hid,
      name : projectName[hid],
      cells: hcells
    });
  }

  data.heatLegend = [
    { key: 'green', label: gs.getMessage('Green') },
    { key: 'amber', label: gs.getMessage('Yellow') },
    { key: 'red',   label: gs.getMessage('Red') },
    { key: 'none',  label: gs.getMessage('No report') }
  ];


  /* ---------- reports filed each month ----------

     Rings, then a matrix, then bars split by percentage, and
     none of them was the right shape. The honest one is a count
     over time: how many reports went in each month, and how
     many of those carried something that needed attention.

     Two bars per month, the same chart as claimed against paid
     on the reimbursements page, so the two read as one product.
     ------------------------------------------------------- */

  var ratingTotal = healthTotals.green + healthTotals.amber + healthTotals.red;

  data.filed = [];

  var filedPeak = 0;

  for (var fm = 0; fm < monthKeys.length; fm++) {
    var tm = trend[monthKeys[fm]] || { green: 0, amber: 0, red: 0 };
    var all = tm.green + tm.amber + tm.red;
    var flagged = tm.amber + tm.red;

    if (all > filedPeak) filedPeak = all;

    data.filed.push({
      month  : data.months[fm],
      total  : all,
      flagged: flagged
    });
  }

  /* A peak of one should not draw a bar the full height of the
     plot, so the axis never tops out below two. */
  var filedTop = Math.max(2, filedPeak);

  for (var fp = 0; fp < data.filed.length; fp++) {
    data.filed[fp].totalPct   = Math.round((data.filed[fp].total / filedTop) * 100);
    data.filed[fp].flaggedPct = Math.round((data.filed[fp].flagged / filedTop) * 100);
  }

  data.filedTop = filedTop;
  data.filedMid = Math.round(filedTop / 2);
  data.hasFiled = filedPeak > 0;


  /* ---------- where the pressure has been ----------

     Counts as horizontal bars against the largest of them, not
     a percentage split. The split is what made every bar full
     width when there was only one report to divide.
     ------------------------------------------------------- */

  var PRESSURE = [
    { key: 'schedule',  label: gs.getMessage('Schedule') },
    { key: 'cost',      label: gs.getMessage('Cost') },
    { key: 'resources', label: gs.getMessage('Resources') },
    { key: 'scope',     label: gs.getMessage('Scope') }
  ];

  var pressPeak = 0;

  for (var pi = 0; pi < PRESSURE.length; pi++) {
    var pd = dims[PRESSURE[pi].key];
    if ((pd.amber + pd.red) > pressPeak) pressPeak = pd.amber + pd.red;
  }

  data.pressure = [];

  for (var pj2 = 0; pj2 < PRESSURE.length; pj2++) {
    var pd2 = dims[PRESSURE[pj2].key];
    var bad = pd2.amber + pd2.red;

    data.pressure.push({
      key  : PRESSURE[pj2].key,
      label: PRESSURE[pj2].label,
      count: bad,
      amber: pd2.amber,
      red  : pd2.red,
      /* a zero stays at zero. A dimension that has never gone
         amber should read as empty, not as a token stub. */
      width: pressPeak ? Math.round((bad / pressPeak) * 100) : 0,
      clean: bad === 0
    });
  }

  data.pressure.sort(function (a, b) {
    return ((b.red * 2) + b.amber) - ((a.red * 2) + a.amber);
  });

  data.hasPressure = ratingTotal > 0;

  data.pressureNote = !ratingTotal ? ''
    : (pressPeak
        ? ratingTotal + ' ' + gs.getMessage('ratings filed in total')
        : gs.getMessage('Every rating you have filed has been green.'));


  /* ---------- change requests ----------

     The same horizontal count bars, so the panel matches the
     one beside it. One request used to render as a full width
     saturated bar with a 1 in it, which was a lot of ink for
     one number.
     ------------------------------------------------------- */

  var OUTCOMES = [
    { key: 'wait',  label: gs.getMessage('Awaiting a decision'), count: approval.requested },
    { key: 'good',  label: gs.getMessage('Approved'),            count: approval.approved },
    { key: 'bad',   label: gs.getMessage('Rejected'),            count: approval.rejected },
    { key: 'draft', label: gs.getMessage('Not yet requested'),   count: approval.notyet }
  ];

  var outPeak = 0;
  var outTotal = 0;

  for (var oi = 0; oi < OUTCOMES.length; oi++) {
    outTotal += OUTCOMES[oi].count;
    if (OUTCOMES[oi].count > outPeak) outPeak = OUTCOMES[oi].count;
  }

  data.outcomes = [];

  for (var oj = 0; oj < OUTCOMES.length; oj++) {
    data.outcomes.push({
      key  : OUTCOMES[oj].key,
      label: OUTCOMES[oj].label,
      count: OUTCOMES[oj].count,
      width: outPeak ? Math.round((OUTCOMES[oj].count / outPeak) * 100) : 0,
      clean: OUTCOMES[oj].count === 0
    });
  }

  var changeDecided = approval.approved + approval.rejected;

  /* An approval rate over no decisions is undefined, not zero. */
  data.changeNote = !outTotal ? ''
    : (changeDecided
        ? Math.round((approval.approved / changeDecided) * 100) + '% ' +
          gs.getMessage('approved of') + ' ' + changeDecided + ' ' + gs.getMessage('decided')
        : gs.getMessage('Nothing decided yet.'));

  data.hasChanges = outTotal > 0;

  /* the categories, as a plain list. One chart per panel. */
  var catRows = [];

  for (var cn in byCategory) {
    catRows.push({
      label   : cn,
      raised  : byCategory[cn].raised,
      approved: byCategory[cn].approved
    });
  }

  catRows.sort(function (a, b) { return b.raised - a.raised; });

  data.byCategory = [];

  for (var cr = 0; cr < catRows.length && cr < 6; cr++) {
    data.byCategory.push({
      label   : catRows[cr].label,
      raised  : catRows[cr].raised,
      approved: catRows[cr].approved
    });
  }

  data.approval = approval;


  /* ---------- who still owes a report this month ---------- */
  data.due = [];

  for (var dp = 0; dp < data.projects.length; dp++) {
    var proj = data.projects[dp];
    if (proj.open && !reportedThisMonth[proj.sysId]) {
      data.due.push({ sysId: proj.sysId, name: proj.name, number: proj.number });
    }
  }


  /* ---------- tiles ---------- */
  var totalReports = data.reports.length;
  var openChanges  = approval.requested + approval.notyet;

  data.tiles = [
    {
      key  : 'due',
      label: gs.getMessage('Reports due this month'),
      value: '' + data.due.length,
      note : data.due.length
               ? gs.getMessage('open projects with nothing filed yet')
               : gs.getMessage('every open project has reported'),
      alert: data.due.length > 0
    },
    {
      key  : 'reports',
      label: gs.getMessage('Reports filed'),
      value: '' + totalReports,
      note : gs.getMessage('across') + ' ' + data.projects.length + ' ' +
             (data.projects.length === 1 ? gs.getMessage('project') : gs.getMessage('projects'))
    },
    {
      key  : 'health',
      label: gs.getMessage('Reported green'),
      /* a percentage over no reports is undefined, not zero */
      value: totalReports ? Math.round((healthTotals.green / totalReports) * 100) + '%' : '—',
      note : totalReports
               ? healthTotals.amber + ' ' + gs.getMessage('yellow') + ', ' +
                 healthTotals.red + ' ' + gs.getMessage('red')
               : gs.getMessage('nothing reported yet')
    },
    {
      key  : 'changes',
      label: gs.getMessage('Change requests'),
      value: '' + data.changes.length,
      note : approval.approved + ' ' + gs.getMessage('approved') + ', ' +
             openChanges + ' ' + gs.getMessage('waiting')
    }
  ];


  /* ============================================================
     CHOICES

     Read from the dictionary, with the values from your forms as
     the fallback for when sys_choice is not readable by an
     external account.

     ADJUST the fallback values if any differ from the
     dictionary, because a wrong value saves an empty field
     without complaining.
     ============================================================ */

  var FALLBACK = {
    report_status: [
      { value: 'Monthly Report',  label: 'Monthly Report' },
      { value: 'Baseline Report', label: 'Baseline Report' },
      { value: 'Final Report',    label: 'Final Report' }
    ],
    health: [
      { value: 'Green',  label: 'Green' },
      { value: 'Yellow', label: 'Yellow' },
      { value: 'Red',    label: 'Red' }
    ],
    priority: [
      { value: '1 - Critical', label: '1 - Critical' },
      { value: '2 - High',     label: '2 - High' },
      { value: '3 - Moderate', label: '3 - Moderate' },
      { value: '4 - Low',      label: '4 - Low' },
      { value: '5 - Planning', label: '5 - Planning' }
    ],
    impact: [
      { value: '1 - High',   label: '1 - High' },
      { value: '2 - Medium', label: '2 - Medium' },
      { value: '3 - Low',    label: '3 - Low' }
    ],
    category: [
      { value: 'Resource', label: 'Resource' },
      { value: 'Scope',    label: 'Scope' },
      { value: 'Schedule', label: 'Schedule' },
      { value: 'Cost',     label: 'Cost' }
    ]
  };

  function choicesFor(table, element, fallbackKey) {

    var out = [];

    try {
      var c = new GlideRecordSecure('sys_choice');
      c.addQuery('name', table);
      c.addQuery('element', element);

      /* language is often blank on scoped choices and inactive
         is frequently null rather than false, and filtering on
         both is what returns an empty list */
      var lang = c.addQuery('language', 'en');
      lang.addOrCondition('language', '');
      lang.addOrCondition('language', 'NULL');

      var act = c.addQuery('inactive', false);
      act.addOrCondition('inactive', '');

      c.orderBy('sequence');
      c.query();

      while (c.next()) {
        var v = c.getValue('value');
        if (!v) continue;
        out.push({ value: v, label: c.getValue('label') || v });
      }
    } catch (e) {
      gs.info('[Reports] sys_choice unreadable for ' + element);
    }

    return out.length ? out : (FALLBACK[fallbackKey] || []);
  }

  data.choices = {
    reportStatus: choicesFor(REPORT, 'report_status', 'report_status'),
    health      : choicesFor(REPORT, 'overall_health', 'health'),
    schedule    : choicesFor(REPORT, 'schedule', 'health'),
    cost        : choicesFor(REPORT, 'cost', 'health'),
    resources   : choicesFor(REPORT, 'resources', 'health'),
    scope       : choicesFor(REPORT, 'scope', 'health'),
    priority    : choicesFor(CHANGE, 'priority', 'priority'),
    impact      : choicesFor(CHANGE, 'impact', 'impact'),
    category    : choicesFor(CHANGE, 'category', 'category')
  };

  data.today = new GlideDate().getValue();


  /* ============================================================
     COPY
     ============================================================ */

  data.t = {
    title : opt('label_title', gs.getMessage('Reports and change requests')),
    search: gs.getMessage('Search by project, reference or title'),

    /* The old heading named the component rather than saying
       what it shows. Nobody looks at a page to see a heat map. */
    heatTitle: gs.getMessage('Six months at a glance'),
    heatHint : gs.getMessage('One square per project per month. The colour is the health that report carried, and an empty square means nothing was filed.'),
    heatEmpty: gs.getMessage('No projects to report on yet.'),

    filedTitle: gs.getMessage('Reports filed each month'),
    filedHint : gs.getMessage('How many went in, and how many of those carried something that needed attention'),
    filedEmpty: gs.getMessage('Nothing filed in the last six months.'),
    filedKeyAll: gs.getMessage('Filed'),
    filedKeyBad: gs.getMessage('Needed attention'),

    pressTitle: gs.getMessage('Where the pressure has been'),
    pressHint : gs.getMessage('How many times each of the four has been rated amber or red'),
    pressEmpty: gs.getMessage('Nothing has been rated yet.'),
    pressClean: gs.getMessage('never'),

    outTitle: gs.getMessage('Change requests'),
    outHint : gs.getMessage('Where every request you have raised currently stands'),
    outEmpty: gs.getMessage('No change requests raised yet.'),
    catByKind: gs.getMessage('By category'),
    catApproved: gs.getMessage('approved'),
    catRaised  : gs.getMessage('raised'),

    dueTitle: gs.getMessage('Still to report this month'),
    dueNone : gs.getMessage('Every open project has reported this month.'),

    tabReports: gs.getMessage('Status reports'),
    tabChanges: gs.getMessage('Change requests'),

    newReport: gs.getMessage('Submit a report'),
    newChange: gs.getMessage('Raise a change request'),
    cancel   : gs.getMessage('Cancel'),
    submit   : gs.getMessage('Submit'),
    saving   : gs.getMessage('Saving'),
    view     : gs.getMessage('View'),
    close    : gs.getMessage('Close'),
    clear    : gs.getMessage('Clear'),

    colPeriod : gs.getMessage('Period'),
    colProject: gs.getMessage('Project'),
    colType   : gs.getMessage('Type'),
    colHealth : gs.getMessage('Health'),
    colFiled  : gs.getMessage('Filed'),
    colRef    : gs.getMessage('Reference'),
    colTitle  : gs.getMessage('Title'),
    colCat    : gs.getMessage('Category'),
    colRaised : gs.getMessage('Raised'),
    colState  : gs.getMessage('Approval'),
    colAction : gs.getMessage('Action'),

    fProject   : gs.getMessage('Project'),
    fStatusDate: gs.getMessage('Status date'),
    fType      : gs.getMessage('Report status'),
    fPercent   : gs.getMessage('Percent complete'),
    fOverall   : gs.getMessage('Overall health'),
    fSummary   : gs.getMessage('Executive summary'),
    fComments  : gs.getMessage('Comments'),
    fAchieved  : gs.getMessage('Achievements last month'),
    fNextUp    : gs.getMessage('Key activities next month'),
    fSchedule  : gs.getMessage('Schedule'),
    fCSchedule : gs.getMessage('Comments on schedule'),
    fCost      : gs.getMessage('Cost'),
    fCCost     : gs.getMessage('Comments on cost'),
    fResources : gs.getMessage('Resources'),
    fCResource : gs.getMessage('Resource comments'),
    fScope     : gs.getMessage('Scope'),
    fCScope    : gs.getMessage('Comments on scope'),

    fTitle    : gs.getMessage('Title'),
    fCategory : gs.getMessage('Category'),
    fPriority : gs.getMessage('Priority'),
    fImpact   : gs.getMessage('Impact'),
    fProposed : gs.getMessage('Proposed change'),
    fReason   : gs.getMessage('Reason for change'),
    fFiles    : gs.getMessage('Supporting documents'),

    dropTitle : gs.getMessage('Drop files here'),
    dropText  : gs.getMessage('PDF, Word or image files, up to 10MB each'),
    dropBtn   : gs.getMessage('Choose files'),
    dropNote  : gs.getMessage('Optional. Anything that backs up what you have written.'),
